<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue';
import {useRouter} from 'vue-router';
import {latestPackage} from '../api';
import {db,queueAttempt,syncAttempts} from '../offline/db';
import type {AttemptEvent,ContentItem} from '../domain';
import {buildUnits,loadVocabularyProgress,saveVocabularyProgress,unitIndexForWord,WORDS_PER_CHAPTER,WORDS_PER_UNIT,type VocabularyProgress} from '../game/vocabularyCourse';
import VocabularyImage from '../components/VocabularyImage.vue';

type Mode='hub'|'learn'|'quiz'|'complete';
const router=useRouter();const allItems=ref<ContentItem[]>([]);const mode=ref<Mode>('hub');const chapter=ref(0);const unitIndex=ref(0);const learnIndex=ref(0);const quizIndex=ref(0);const options=ref<ContentItem[]>([]);const mistakes=ref(0);const stars=ref(0);const message=ref('');const search=ref('');const loading=ref(true);const sound=ref(true);const progressState=ref<VocabularyProgress>({completedUnits:[]});
let packageVersion='unknown',sessionId=crypto.randomUUID(),started=0,timer:ReturnType<typeof setTimeout>|undefined;
const units=computed(()=>buildUnits(allItems.value));const chapters=computed(()=>Math.max(1,Math.ceil(allItems.value.length/WORDS_PER_CHAPTER)));
const chapterUnits=computed(()=>{const start=chapter.value*(WORDS_PER_CHAPTER/WORDS_PER_UNIT);return units.value.slice(start,start+WORDS_PER_CHAPTER/WORDS_PER_UNIT).map((items,i)=>({items,index:start+i}))});
const currentUnit=computed(()=>units.value[unitIndex.value]??[]);const currentLearn=computed(()=>currentUnit.value[learnIndex.value]);const currentQuiz=computed(()=>currentUnit.value[quizIndex.value]);
const completedCount=computed(()=>progressState.value.completedUnits.length);const completion=computed(()=>units.value.length?Math.round(completedCount.value/units.value.length*100):0);
const firstIncomplete=computed(()=>units.value.findIndex((_,i)=>!progressState.value.completedUnits.includes(i)));
function speak(text:string,lang='en-US'){if(!sound.value||!text||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=lang==='zh-CN'?0.9:0.8;u.pitch=1.04;window.speechSynthesis.speak(u)}
function openUnit(index:number){if(!units.value[index]?.length)return;unitIndex.value=index;learnIndex.value=0;quizIndex.value=0;stars.value=0;mistakes.value=0;sessionId=crypto.randomUUID();mode.value='learn';message.value='先认识这一组单词。点喇叭多听几遍。';nextTick(()=>speak(currentLearn.value?.text))}
function previousLearn(){if(learnIndex.value<=0)return;learnIndex.value--;speak(currentLearn.value.text)}
function nextLearn(){if(learnIndex.value+1<currentUnit.value.length){learnIndex.value++;speak(currentLearn.value.text)}else{quizIndex.value=0;mode.value='quiz';prepareQuiz();message.value='听英文，选择正确的中文意思。'}}
function shuffle<T>(a:T[],seed:number){const x=[...a];for(let i=x.length-1;i>0;i--){const j=(seed*13+i*7+quizIndex.value*5)%(i+1);[x[i],x[j]]=[x[j],x[i]]}return x}
function prepareQuiz(){const target=currentQuiz.value;if(!target)return;const rest=allItems.value.filter(x=>x.id!==target.id);options.value=shuffle([target,...shuffle(rest,unitIndex.value+7).slice(0,3)],unitIndex.value+quizIndex.value+11);mistakes.value=0;started=performance.now();setTimeout(()=>speak(target.text),220)}
async function record(correctFirst:boolean){
 const target=currentQuiz.value;if(!target)return;
 const e:AttemptEvent={eventId:crypto.randomUUID(),sessionId,contentItemId:target.id,packageVersion,activityVersion:1,firstTryCorrect:correctFirst,semanticErrors:mistakes.value,hintLevel:0,responseMs:Math.round(performance.now()-started),occurredAt:new Date().toISOString(),syncStatus:'PENDING',worldId:'vocabulary-library',stageId:'vocab-unit-'+(unitIndex.value+1),activityType:'LISTEN_MEANING'};
 try{await queueAttempt(e)}catch{}
}
async function choose(item:ContentItem){const target=currentQuiz.value;if(!target)return;if(item.id!==target.id){mistakes.value++;message.value='再听一次，想想它是什么意思。';speak(target.text);return}const earned=mistakes.value===0?3:mistakes.value===1?2:1;stars.value+=earned;await record(mistakes.value===0);message.value='答对啦！⭐ +'+earned;timer=setTimeout(()=>{if(quizIndex.value+1>=currentUnit.value.length)finishUnit();else{quizIndex.value++;prepareQuiz();message.value='继续听，下一个单词。'}},750)}
function finishUnit(){mode.value='complete';if(!progressState.value.completedUnits.includes(unitIndex.value)){progressState.value.completedUnits=[...progressState.value.completedUnits,unitIndex.value].sort((a,b)=>a-b);saveVocabularyProgress(progressState.value)}message.value='第 '+(unitIndex.value+1)+' 单元完成！';sync()}
function nextUnit(){const n=Math.min(units.value.length-1,unitIndex.value+1);chapter.value=Math.floor(n/(WORDS_PER_CHAPTER/WORDS_PER_UNIT));openUnit(n)}
function backToHub(){mode.value='hub';chapter.value=Math.floor(unitIndex.value/(WORDS_PER_CHAPTER/WORDS_PER_UNIT))}
function searchWord(){const q=search.value.trim();if(!q)return;const index=unitIndexForWord(allItems.value,q);if(index<0){message.value='没有在已发布词库中找到 “'+q+'”';return}chapter.value=Math.floor(index/(WORDS_PER_CHAPTER/WORDS_PER_UNIT));openUnit(index)}
function continueLearning(){openUnit(firstIncomplete.value>=0?firstIncomplete.value:0)}
function sync(){syncAttempts(localStorage.getItem('kidToken')??'').catch(()=>{})}
async function load(){progressState.value=loadVocabularyProgress();try{const pkg=await latestPackage();packageVersion=pkg.packageVersion;allItems.value=pkg.items.filter(x=>x.status==='READY');await db.packages.put(pkg)}catch{try{const pkg=await db.packages.orderBy('publishedAt').last();if(pkg){packageVersion=pkg.packageVersion;allItems.value=pkg.items.filter(x=>x.status==='READY')}}catch{}}loading.value=false}
onMounted(()=>void load());onBeforeUnmount(()=>{if(timer)clearTimeout(timer);window.speechSynthesis?.cancel()});
</script>
<template><main class="library"><div class="page">
<header><button class="back" @click="router.push('/kid')">← 世界地图</button><div><small>VOCABULARY ADVENTURE</small><h1>📚 词库学习馆</h1><p>所有已发布单词都会自动进入这里，不再依赖固定场景。</p></div><button class="sound" @click="sound=!sound">{{sound?'🔊':'🔇'}}</button></header>
<div v-if="loading" class="empty">正在整理学习词库…</div>
<div v-else-if="!allItems.length" class="empty"><b>还没有可学习的已发布词汇</b><p>请先在家长端批准并“发布学习包”。</p><router-link to="/parent">前往家长端</router-link></div>
<template v-else>
<section v-if="mode==='hub'" class="hub">
 <div class="overview"><div><span>已发布词汇</span><strong>{{allItems.length}}</strong></div><div><span>学习单元</span><strong>{{units.length}}</strong></div><div><span>已完成</span><strong>{{completedCount}}</strong></div><div><span>总进度</span><strong>{{completion}}%</strong></div></div>
 <div class="hero-card"><img src="/scenes/vocabulary-library.svg" alt="词库学习馆"/><div><small>每天 10 个词</small><h2>把 2000 词变成可以真正学习的 200 个小单元</h2><p>每个单元先认识 10 个词，再进行听音选义。完成后自动记录学习结果。</p><button @click="continueLearning">▶ 继续学习</button></div></div>
 <div class="search-row"><input v-model="search" placeholder="输入英文单词，例如 apple" @keyup.enter="searchWord"/><button @click="searchWord">查找并学习</button></div><p v-if="message" class="notice">{{message}}</p>
 <nav class="chapters"><button v-for="n in chapters" :key="n" :class="{active:chapter===n-1}" @click="chapter=n-1">第 {{n}} 章<small>{{(n-1)*200+1}}–{{Math.min(n*200,allItems.length)}} 词</small></button></nav>
 <div class="units"><button v-for="u in chapterUnits" :key="u.index" :class="{done:progressState.completedUnits.includes(u.index)}" @click="openUnit(u.index)"><span>UNIT {{u.index+1}}</span><b>{{u.items[0]?.text}} → {{u.items[u.items.length-1]?.text}}</b><small>{{u.items.length}} 个词</small><em>{{progressState.completedUnits.includes(u.index)?'✅ 已完成':'开始学习 →'}}</em></button></div>
</section>
<section v-else class="lesson">
 <div class="lesson-top"><button @click="backToHub">← 单元列表</button><div><small>UNIT {{unitIndex+1}} · {{currentUnit.length}} WORDS</small><h2>{{mode==='learn'?'① 认识新词':mode==='quiz'?'② 听音选义':'🎉 单元完成'}}</h2></div><span>⭐ {{stars}}</span></div>
 <div class="unit-strip"><span v-for="(item,i) in currentUnit" :key="item.id" :class="{active:(mode==='learn'?learnIndex:quizIndex)===i,done:mode!=='learn'&&i<quizIndex}">{{i+1}}</span></div>
 <div v-if="mode==='learn'&&currentLearn" class="learn-card"><div class="word-index">WORD {{learnIndex+1}} / {{currentUnit.length}}</div><VocabularyImage class="learn-image" :word="currentLearn.text" :asset-key="currentLearn.assetKey" :alt="currentLearn.meaningCn" size="large"/><div class="learn-copy"><h3>{{currentLearn.text}}</h3><p>{{currentLearn.meaningCn}}</p></div><div class="voice-actions"><button @click="speak(currentLearn.text)">🔊 听英文</button><button class="cn" @click="speak(currentLearn.meaningCn,'zh-CN')">🔈 听中文</button></div><div class="learn-nav"><button class="plain" :disabled="learnIndex===0" @click="previousLearn">← 上一个单词</button><button class="next" @click="nextLearn">{{learnIndex+1===currentUnit.length?'开始小测验 →':'下一个单词 →'}}</button></div></div>
 <div v-if="mode==='quiz'&&currentQuiz" class="quiz-card"><small>LISTEN & CHOOSE · {{quizIndex+1}} / {{currentUnit.length}}</small><h3>听一听，它是什么意思？</h3><button class="listen" @click="speak(currentQuiz.text)">🔊 再听一次</button><div class="meaning-options"><button v-for="item in options" :key="item.id" @click="choose(item)"><span>{{item.meaningCn}}</span><i @click.stop="speak(item.meaningCn,'zh-CN')">🔈</i></button></div><p>{{message}}</p></div>
 <div v-if="mode==='complete'" class="complete"><img src="/scenes/vocabulary-library.svg" alt="完成"/><h2>{{message}}</h2><div class="big-stars">⭐ {{stars}} / {{currentUnit.length*3}}</div><p>这 10 个词已经有了第一轮学习记录，之后仍可以回到本单元复习。</p><div><button class="plain" @click="openUnit(unitIndex)">再学一次</button><button v-if="unitIndex+1<units.length" @click="nextUnit">下一个单元 →</button><button v-else @click="backToHub">返回词库</button></div></div>
 </section>
</template>
</div></main></template>
<style scoped>
.library{min-height:100vh;background:radial-gradient(circle at 10% 5%,#fff0d5,transparent 28%),radial-gradient(circle at 90% 7%,#d9f4f1,transparent 28%),#f3f7ff;color:#3e4d67;font-family:system-ui,"Microsoft YaHei",sans-serif}.page{max-width:1100px;margin:auto;padding:20px 22px 60px}header{display:flex;align-items:center;justify-content:space-between;gap:18px;background:#fff;padding:18px 22px;border-radius:25px;box-shadow:0 8px 0 #e0e5f2}header>div{text-align:center}header small{font-size:10px;letter-spacing:1.5px;color:#927fcd;font-weight:900}header h1{margin:3px;color:#5d4ca4}header p{margin:3px;color:#7e8796;font-size:12px}.back,.sound{border:0;border-radius:14px;background:#eeeafd;color:#6653b0;padding:11px 14px;font-weight:850}.sound{font-size:20px}.empty{background:#fff;margin-top:22px;padding:50px;text-align:center;border-radius:24px}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.overview>div{background:#fff;border-radius:20px;padding:16px 20px;box-shadow:0 5px 0 #e5e8f3}.overview span{font-size:11px;color:#8a92a0}.overview strong{display:block;font-size:28px;color:#715bc3}.hero-card{display:grid;grid-template-columns:300px 1fr;gap:24px;align-items:center;background:#fff;border-radius:28px;padding:18px;box-shadow:0 8px 0 #dfe4f0}.hero-card img{width:100%;border-radius:20px}.hero-card small{color:#8f7dcc;font-weight:900}.hero-card h2{color:#5e4ea6;margin:7px 0;font-size:27px}.hero-card p{color:#777f90;line-height:1.7}.hero-card button,.search-row button,.lesson button{border:0;background:#806bd1;color:#fff;border-radius:15px;padding:12px 18px;font-weight:900;cursor:pointer}.search-row{display:flex;gap:10px;margin:18px 0}.search-row input{flex:1;border:1px solid #dadfec;border-radius:15px;padding:13px 15px}.notice{background:#fff7d8;border-radius:12px;padding:9px 12px;color:#856a2b}.chapters{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:18px 0}.chapters button{border:2px solid #fff;background:#fff;border-radius:17px;padding:11px;color:#6e668e;box-shadow:0 4px 0 #e0e4ef}.chapters button.active{background:#eee9ff;border-color:#b6a5ee}.chapters small{display:block;font-size:9px;color:#999}.units{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.units button{text-align:left;border:3px solid #fff;background:#fff;border-radius:20px;padding:15px;box-shadow:0 6px 0 #dfe3ef;color:#555f76;cursor:pointer}.units span,.units small,.units em{display:block}.units span{font-size:10px;font-weight:900;color:#9a87cf}.units b{display:block;margin:5px 0;color:#5e4ea1}.units small{color:#939aa8}.units em{margin-top:9px;color:#4c9a77;font-style:normal;font-size:11px;font-weight:850}.units button.done{background:#f0faf4;box-shadow:0 6px 0 #c9e7d5}.lesson{margin-top:18px}.lesson-top{display:flex;align-items:center;justify-content:space-between;background:#fff;padding:13px 17px;border-radius:20px}.lesson-top h2{margin:2px;color:#5f4ea5}.lesson-top small{color:#9a89cc;font-weight:900}.unit-strip{display:flex;gap:7px;justify-content:center;margin:16px}.unit-strip span{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:#fff;color:#7b8293;font-size:11px;font-weight:900}.unit-strip span.active{background:#816bd1;color:#fff;transform:scale(1.12)}.unit-strip span.done{background:#84d1aa;color:#fff}.learn-card,.quiz-card,.complete{max-width:720px;margin:18px auto;background:#fffefa;border:6px solid #fff;border-radius:32px;padding:30px;text-align:center;box-shadow:0 12px 0 #d8d6ea}.learn-card{display:flex;flex-direction:column;align-items:center;gap:15px}.word-index{position:relative;z-index:2;display:inline-flex;align-items:center;justify-content:center;background:#f0ebff;color:#7b68cf;border-radius:999px;padding:8px 16px;font-size:13px;font-weight:900;letter-spacing:.5px;line-height:1}.learn-image{margin:0 auto}.learn-copy{text-align:center}.learn-card small,.quiz-card small{color:#9987ce;font-weight:900}.learn-card h3{font-size:46px;line-height:1.05;color:#5e4da4;margin:0}.learn-card p{font-size:25px;color:#687489;margin:7px 0 0}.voice-actions{display:flex;justify-content:center;gap:10px;margin:5px 0 3px}.voice-actions .cn,.plain{background:#ece9f8!important;color:#6558a2!important}.learn-nav{display:flex;justify-content:center;gap:10px;flex-wrap:wrap}.learn-nav .plain:disabled{opacity:.45;cursor:not-allowed}.next{font-size:16px}.quiz-card h3{font-size:27px;color:#5e4da4}.listen{font-size:18px}.meaning-options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.meaning-options button{display:flex;align-items:center;justify-content:space-between;gap:8px;background:#f5f3fc;color:#5b6172;border:3px solid #ebe6f9;padding:17px;text-align:left}.meaning-options i{font-style:normal;background:#fff;padding:5px;border-radius:10px}.complete img{width:230px;border-radius:20px}.complete h2{color:#5f4da5}.big-stars{font-size:35px;color:#d69335;font-weight:950;margin:10px}.complete>div:last-child{display:flex;gap:10px;justify-content:center}.complete p{color:#788191}@media(max-width:760px){.page{padding:10px}.overview{grid-template-columns:repeat(2,1fr)}.hero-card{grid-template-columns:1fr}.hero-card img{max-height:190px;object-fit:cover}.chapters{grid-template-columns:repeat(2,1fr)}.units{grid-template-columns:repeat(2,1fr)}.meaning-options{grid-template-columns:1fr}header p{display:none}.back{font-size:0}.back::after{content:'←';font-size:18px}}</style>
